"""A v31 record can undo the latest existing mark without renumbering or losing unrelated fields."""
import sys
from pathlib import Path
from playwright.sync_api import sync_playwright
url=sys.argv[1];fixture=Path(__file__).resolve().parents[1]/'no-unit.dxf'
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',headless=True);page=b.new_page(viewport={'width':390,'height':590});page.goto(url);page.locator('#file').set_input_files(str(fixture));page.locator('.drawing-item').first.wait_for()
 page.evaluate('''() => new Promise((resolve,reject)=>{let o=indexedDB.open('vidoviewer-library');o.onsuccess=()=>{let db=o.result,tx=db.transaction('drawings','readwrite'),s=tx.objectStore('drawings'),q=s.getAll();q.onsuccess=()=>{let r=q.result[0],a={kind:'distance',points:[{x:0,y:0},{x:10,y:0}]},b={kind:'distance',points:[{x:0,y:40},{x:20,y:40}]};r.extraField={keep:'yes'};r.nextMarkNumber=28;r.marks=[{key:'old-a',number:12,measurement:a,unit:null,label:'距離 10 圖面單位',extra:'keep'},{key:'old-b',number:27,measurement:b,unit:null,label:'距離 20 圖面單位'}];r.measurementState={current:{tool:'distance',measurement:b,activeMarkKey:'old-b',unit:null},history:[{tool:'distance',measurement:b,activeMarkKey:null,unit:null}]};s.put(r)};tx.oncomplete=()=>{db.close();resolve()};tx.onerror=()=>reject(tx.error)}})''')
 page.locator('.drawing-item').first.click();page.locator('#viewerLayer').wait_for(state='visible');page.wait_for_function("() => document.querySelector('#drawing').dataset.markCount==='2'");page.click('#undoMeasurement');page.wait_for_function("() => document.querySelector('#drawing').dataset.markCount==='1'");assert page.locator('#resultValue').inner_text()=='10';page.reload();page.locator('#viewerLayer').wait_for(state='visible');page.wait_for_function("() => document.querySelector('#drawing').dataset.markCount==='1'")
 data=page.evaluate('''() => new Promise((resolve,reject)=>{let o=indexedDB.open('vidoviewer-library');o.onsuccess=()=>{let db=o.result,q=db.transaction('drawings').objectStore('drawings').getAll();q.onsuccess=()=>{let r=q.result[0];resolve({extra:r.extraField.keep,markExtra:r.marks[0].extra,number:r.marks[0].number,next:r.nextMarkNumber,key:r.marks[0].key,size:r.size ?? r.blob.size});db.close()};q.onerror=()=>reject(q.error)}})''')
 assert data=={'extra':'yes','markExtra':'keep','number':12,'next':28,'key':'old-a','size':fixture.stat().st_size},data
 page.click('#undoMeasurement');page.wait_for_function("() => document.querySelector('#drawing').dataset.markCount==='0'");assert page.locator('#undoMeasurement').is_disabled()
 print('PASS v31 migration, undo latest, stable numbering and unrelated fields:',url);b.close()
